    @Override
    public Function<ResultRow, Object> prepareForCache(boolean isResultLevelCache)
    {
      final boolean resultRowHasTimestamp = query.getResultRowHasTimestamp();

      return new Function<ResultRow, Object>()
      {
        @Override
        public Object apply(ResultRow resultRow)
        {
          final List<Object> retVal = new ArrayList<>(1 + dims.size() + aggs.size());
          int inPos = 0;

          if (resultRowHasTimestamp) {
            retVal.add(resultRow.getLong(inPos++));
          } else {
            retVal.add(query.getUniversalTimestamp().getMillis());
          }

          for (int i = 0; i < dims.size(); i++) {
            retVal.add(resultRow.get(inPos++));
          }
          for (int i = 0; i < aggs.size(); i++) {
            retVal.add(resultRow.get(inPos++));
          }
          if (isResultLevelCache) {
            for (int i = 0; i < query.getPostAggregatorSpecs().size(); i++) {
              retVal.add(resultRow.get(inPos++));
            }
          }
          return retVal;
        }
      };
    }

    @Override
    public Function<Object, ResultRow> pullFromCache(boolean isResultLevelCache)
    {
      return new Function<Object, ResultRow>()
      {
        private final Granularity granularity = query.getGranularity();

        @Override
        public ResultRow apply(Object input)
        {
          final List<Object> cachedRow = (List<Object>) input;
          final Iterator<Object> results = cachedRow.iterator();

          final Object timestampObj = results.next();
          final long timestampMillis = ((Number) timestampObj).longValue();
          final DateTime timestamp = granularity.toDateTime(timestampMillis);

          final boolean includeTimestamp = query.getUniversalTimestamp() == null;
          final List<DimensionSpec> queryDimensions = query.getDimensions();
          final List<AggregatorFactory> queryAggregators = query.getAggregatorSpecs();
          final int dimensionCount = queryDimensions.size();
          final int aggregatorCount = queryAggregators.size();
          final int postAggregatorCount = query.getPostAggregatorSpecs().size();

          int dimensionStart = 0;
          if (includeTimestamp) {
            dimensionStart = 1;
          }
          final int aggregatorStart = dimensionStart + dimensionCount;
          final int postAggregatorStart = aggregatorStart + aggregatorCount;

          int size = postAggregatorStart;
          if (isResultLevelCache) {
            size += postAggregatorCount;
          }

          final ResultRow resultRow = ResultRow.create(size);
          if (includeTimestamp) {
            resultRow.set(0, timestamp.getMillis());
          }

          final Iterator<DimensionSpec> dimsIter = queryDimensions.iterator();
          int dimPos = 0;
          while (dimsIter.hasNext()) {
            if (!results.hasNext()) {
              break;
            }
            final DimensionSpec dimensionSpec = dimsIter.next();
            final Object rawValue = results.next();
            final ColumnType outputType = dimensionSpec.getOutputType();
            final Object convertedValue;
            if (outputType != null) {
              if (ValueType.LONG.equals(outputType.getType())) {
                if (rawValue == null) {
                  convertedValue = null;
                } else {
                  convertedValue = DimensionHandlerUtils.convertObjectToLong(rawValue, false);
                }
              } else {
                convertedValue = DimensionHandlerUtils.convertObjectToType(rawValue, outputType);
              }
            } else {
              convertedValue = DimensionHandlerUtils.convertObjectToType(rawValue, outputType);
            }
            resultRow.set(dimensionStart + dimPos, convertedValue);
            dimPos++;
          }

          for (int aggPosition = 0; aggPosition < aggregatorCount; aggPosition++) {
            if (!results.hasNext()) {
              throw new ISE("Ran out of objects while reading aggregators from cache!");
            }
            final AggregatorFactory aggregator = queryAggregators.get(aggPosition);
            final Object rawAggValue = results.next();
            if (isResultLevelCache) {
              resultRow.set(aggregatorStart + aggPosition, rawAggValue);
            } else {
              resultRow.set(aggregatorStart + aggPosition, aggregator.deserialize(rawAggValue));
            }
          }

          if (isResultLevelCache) {
            Iterator<PostAggregator> postItr = query.getPostAggregatorSpecs().iterator();
            int postPos = 0;
            while (postItr.hasNext() && results.hasNext()) {
              resultRow.set(postAggregatorStart + postPos, results.next());
            }
          }
          if (dimsIter.hasNext() || results.hasNext()) {
            throw new ISE(
                "Found left over objects while reading from cache!! dimsIter[%s] results[%s]",
                dimsIter.hasNext(),
                results.hasNext()
            );
          }

          return resultRow;
        }
      };
    }
  };
}

